// Garde l'image pour /roborock-map.png et passe l'état à la suite
flow.set('roborockPng', msg.payload);
msg.robot = {
    etat: msg.status && msg.status.stateText,
    batterie: msg.status && msg.status.battery,
    piece: msg.map.robot && msg.map.robot.room ? (msg.map.robot.room.name || ('pièce ' + msg.map.robot.room.id)) : null
};
return msg;

const png = flow.get('roborockPng');
if (!png) {
    msg.statusCode = 404;
    msg.payload = 'Carte pas encore disponible';
    msg.headers = { 'Content-Type': 'text/plain' };
    return msg;
}
msg.statusCode = 200;
msg.payload = png;
msg.headers = { 'Content-Type': 'image/png', 'Cache-Control': 'no-store' };
return msg;
